formData.jsFunction:
def addError(response, key, msg) {
    if (response[key] == null) response[key] = msg
    else if (response[key] instanceof List) response[key] << msg
    else response[key] = [response[key], msg]
}

def validate(request, response = [:]) {

    if (!request) {
        addError(response, "data", "The data/formData key is required")
        return response
    }
    def data = request.data ?: [:]
    if (!data.containsKey("isAdhoc")) {
        return response
    } else {
        def columns = data.columns ?: []
        if (columns.size() == 0) {
            addError(response, "columns", "No columns are selected.")
            return response
        } else {
            return response
        }
    }
}
